function isWideChar(cp) {
  return (
    (cp >= 0x1100 && cp <= 0x115F) ||
    (cp >= 0x2E80 && cp <= 0x303E) ||
    (cp >= 0x3041 && cp <= 0x33FF) ||
    (cp >= 0x3400 && cp <= 0x4DBF) ||
    (cp >= 0x4E00 && cp <= 0x9FFF) ||
    (cp >= 0xA000 && cp <= 0xA4CF) ||
    (cp >= 0xAC00 && cp <= 0xD7A3) ||
    (cp >= 0xF900 && cp <= 0xFAFF) ||
    (cp >= 0xFF00 && cp <= 0xFF60) ||
    (cp >= 0xFFE0 && cp <= 0xFFE6)
  );
}
function xWeightedLength(str) {
  let len = 0;
  for (const ch of str) len += isWideChar(ch.codePointAt(0)) ? 2 : 1;
  return len;
}
function truncateToXLimit(str, limit) {
  if (limit <= 0) return '';
  if (xWeightedLength(str) <= limit) return str;
  const ellipsis = '\u2026';
  const budget = limit - xWeightedLength(ellipsis);
  let result = '';
  let len = 0;
  for (const ch of Array.from(str)) {
    const w = isWideChar(ch.codePointAt(0)) ? 2 : 1;
    if (len + w > budget) break;
    result += ch;
    len += w;
  }
  return result + ellipsis;
}

// reply1(返信1) = Body+Hashtags。Hashtagsを優先的に残し、Bodyだけを自動で切り詰める
function composeReply1(body, hashtags, limit) {
  const sep = '\n\n';
  const sepLen = xWeightedLength(sep);
  let hashtagsPart = hashtags || '';
  let bodyBudget = limit - (hashtagsPart ? sepLen + xWeightedLength(hashtagsPart) : 0);
  if (bodyBudget < 20) {
    hashtagsPart = '';
    bodyBudget = limit;
  }
  const bodyTrunc = bodyBudget > 0 ? truncateToXLimit(body || '', bodyBudget) : '';
  const parts = [bodyTrunc, hashtagsPart].filter(Boolean);
  let result = parts.join(sep);
  if (xWeightedLength(result) > limit) result = truncateToXLimit(result, limit);
  return result;
}

