function truncateTo(str, limit) {
  const chars = Array.from(str || '');
  if (chars.length <= limit) return str || '';
  const ellipsis = '…';
  return chars.slice(0, Math.max(0, limit - 1)).join('') + ellipsis;
}

// reply1(返信1) = Body+Hashtags。Hashtagsを優先的に残し、Bodyだけを自動で切り詰める（Xの実装と同じ優先順位）
function composeReply1(body, hashtags, limit) {
  const sep = '\n\n';
  let hashtagsPart = hashtags || '';
  let bodyBudget = limit - (hashtagsPart ? Array.from(sep).length + Array.from(hashtagsPart).length : 0);
  if (bodyBudget < 20) {
    hashtagsPart = '';
    bodyBudget = limit;
  }
  const bodyTrunc = bodyBudget > 0 ? truncateTo(body || '', bodyBudget) : '';
  const parts = [bodyTrunc, hashtagsPart].filter(Boolean);
  let result = parts.join(sep);
  if (Array.from(result).length > limit) result = truncateTo(result, limit);
  return result;
}

