  if (spec.type === 'thumbnail') {
    // サムネイルは投稿の顔なので、諦めずに投稿全体を失敗させてError Workflowに委ねる
    throw new Error(`Instagramサムネイル画像が${MAX_ATTEMPTS}回試行しても改善しませんでした(${qaText || '画像生成自体に失敗'})`);
  }
  // コンテンツ画像は諦めてカルーセルから除外する(投稿全体は止めない)
  return { json: { ...spec, ok: false, dropped: true, retry: false, b64: null } };
}

// 再試行: 文字の正確さと解剖学的な自然さを補足指示として追記(SEO記事アイキャッチの再試行ロジックと同じ考え方)
const correctivePrompt = `${spec.image_prompt}\n\n(${spec.attempt}回目の生成で問題が見つかったため再生成中。特に文字「${spec.text}」は日本語として完全に正確に、崩れずはっきりと読める形で描画すること。また手足・指の本数や身体バランスも自然になるよう注意すること。)`;

return { json: { ...spec, image_prompt: correctivePrompt, attempt: spec.attempt + 1, retry: true, b64: null } };

const src = $input.first().json;
// TODO: ユーザー提供の固定プロフィール誘導画像のURLが決まったらここに設定する。
// 空のままだと閉じ画像なしでカルーセルを作る(サムネイル+コンテンツ画像のみ)。
const CLOSING_IMAGE_URL = '';

const allUrls = CLOSING_IMAGE_URL ? [...src.image_urls, CLOSING_IMAGE_URL] : src.image_urls;

return allUrls.map((url, i) => ({
  json: {
    page_id: src.page_id,
    name: src.name,
    caption: src.caption,
    image_url: url,
    index: i
  }
}));

// アップロードAPIのレスポンスは{url}のみでtype/index/page_id等が失われるため、
// Base64をBinaryに変換時点のitemを名前参照で復元してからurlを合成する
// (Workflow03のHTTP Request経由フィールド消失と同じ問題、同じ対処)。
const orig = $('Instagram:Base64をBinaryに変換').item.json;
return { json: { ...orig, url: $json.url } };
